using System; class CandarChecks { static void Check(bool v,string m){if(!v)throw new Exception(m);} static void Main(){int draws=0;var min=CandarDiplomacy.RollRansom((a,b)=>{draws++;return a;});Check(draws==16,"eight independent successful rows");Check(min.Infantry==20&&min.Archers==15&&min.Cavalry==1&&min.Engineers==1&&min.Monks==1&&min.Envoy==1&&min.Guards==1&&min.Population==150,"inclusive minima");int chance=0;var max=CandarDiplomacy.RollRansom((a,b)=>{if(a==0&&b==100){chance++;return 0;}return b-1;});Check(chance==8&&max.Infantry==60&&max.Archers==30&&max.Cavalry==5&&max.Engineers==5&&max.Monks==5&&max.Guards==3&&max.Population==300,"inclusive maxima");var failed=CandarDiplomacy.RollRansom((a,b)=>b-1);Check(failed.Cavalry==0&&failed.Engineers==0&&failed.Monks==0&&failed.Envoy==0&&failed.Guards==0&&failed.Population==300,"independent failure thresholds and guaranteed rows");Check(max.OtherResidents==191&&max.Volunteers==109,"population includes every volunteer");Console.WriteLine("PASS: independent rows, inclusive endpoints, chance boundaries, total population accounting");}}